test("instructions cannot masquerade as their own normative attachment or escape the project", () => {
	const f = fixture();
	try {
		f.write("AGENTS.md", "# Project\n## Required standards\n- [Self](AGENTS.md)\n- [Alias](alias.md)\n- [Outside](../outside.md)\n- [Private](file:///private/standards.md)\n");
		symlinkSync("AGENTS.md", path.join(f.root, "alias.md"));
		const codes = f.check().map((issue) => issue.code);
		assert.equal(codes.filter((code) => code === "INSTRUCTIONS_SELF_LINK").length, 2);
		assert.equal(codes.filter((code) => code === "INSTRUCTIONS_LINK_INVALID").length, 2);
	} finally {
		f.clean();
	}
});
